package com.bank.override.model;

import java.io.IOException;
import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private BigDecimal balance;

    public Account(String accountId, BigDecimal balance) {
        this.accountId = accountId;
        this.balance = balance;
    }

    // To be overridden with COVARIANT return:
    public InterestResult calculateInterest() {
        return new InterestResult(BigDecimal.ZERO);
    }

    // To demonstrate ACCESS MODIFIER rule:
    protected void processInternal() {
        // protected — child can widen to public
    }

    // To demonstrate EXCEPTION rule:
    public void loadData() throws IOException {
        // throws IOException — child can narrow
    }

    // FINAL — cannot be overridden:
    public final String getAccountId() { return accountId; }

    // STATIC — hidden, not overridden:
    public static String getBankName() { return "National Bank of India"; }

    public BigDecimal getBalance() { return balance; }
    protected void setBalance(BigDecimal balance) { this.balance = balance; }
}
