// ─── File: src/main/java/com/bank/override/model/SavingsAccount.java ───
package com.bank.override.model;

import java.io.FileNotFoundException;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class SavingsAccount extends Account {
    private final BigDecimal annualRate;

    public SavingsAccount(String accountId, BigDecimal balance, BigDecimal rate) {
        super(accountId, balance);
        this.annualRate = rate;
    }

    // ═══ RULE 1: COVARIANT RETURN TYPE ═══
    @Override
    public SavingsInterestResult calculateInterest() {
        // Returns SavingsInterestResult (subtype of InterestResult) ✅ COVARIANT
        BigDecimal interest = getBalance().multiply(annualRate)
            .divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP);
        return new SavingsInterestResult(interest, annualRate);
    }

    // ═══ RULE 2: ACCESS MODIFIER WIDENED ═══
    @Override
    public void processInternal() {
        // protected → public ✅ WIDER access
        // Savings accounts expose internal processing publicly
    }

    // ═══ RULE 3: EXCEPTION NARROWED ═══
    @Override
    public void loadData() throws FileNotFoundException {
        // IOException → FileNotFoundException ✅ NARROWER (FileNotFoundException extends IOException)
    }

    // ═══ RULE 4: FINAL — cannot override getAccountId() ═══
    // @Override public String getAccountId() { ... }  // ❌ COMPILE ERROR: cannot override final

    // ═══ RULE 4: STATIC — this is HIDING, not overriding ═══
    public static String getBankName() { return "Savings Division"; }
    // Account.getBankName() → "National Bank of India"
    // SavingsAccount.getBankName() → "Savings Division"
    // NO polymorphism! Static binds to CLASS at compile time.
}
```

