```java
// ─── File: src/test/java/com/bank/override/OverrideRulesTest.java ───
package com.bank.override;

import com.bank.override.factory.*;
import com.bank.override.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class OverrideRulesTest {

    // ═══ RULE 1: COVARIANT RETURN TYPE ═══
    @Test
    void rule1_covariantReturn_childReturnsSubtype() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        SavingsInterestResult result = sa.calculateInterest();
        // Return type: SavingsInterestResult (subtype of InterestResult) — no cast needed!
        assertThat(result.getAmount()).isEqualByComparingTo("400");
        assertThat(result.getRate()).isEqualByComparingTo("0.04");  // extra field available!
    }

    @Test
    void rule1_covariantReturn_worksPolymorphically() {
        Account account = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        InterestResult result = account.calculateInterest();
        // Through Account reference: returns InterestResult (parent type)
        // But ACTUAL object is SavingsInterestResult — can cast if needed
        assertThat(result).isInstanceOf(SavingsInterestResult.class);
    }

    @Test
    void rule1_covariantReturn_inFactory() {
        SavingsAccountFactory factory = new SavingsAccountFactory();
        SavingsAccount sa = factory.create("SAV001");  // returns SavingsAccount — no cast!
        assertThat(sa).isInstanceOf(SavingsAccount.class);

        AccountFactory baseFactory = factory;
        Account account = baseFactory.create("SAV002");  // through parent ref: returns Account
        assertThat(account).isInstanceOf(SavingsAccount.class);  // but actual IS SavingsAccount
    }

    // ═══ RULE 2: ACCESS MODIFIER — can widen, not narrow ═══
    @Test
    void rule2_accessWidened() {
        SavingsAccount sa = new SavingsAccount("SAV001", BigDecimal.ZERO, new BigDecimal("0.04"));
        sa.processInternal();  // public — accessible from anywhere ✅
        // Parent's processInternal() was protected — child widened to public
    }

    // ═══ RULE 3: EXCEPTIONS — narrower or removed ═══
    @Test
    void rule3_exceptionNarrowed() throws Exception {
        SavingsAccount sa = new SavingsAccount("SAV001", BigDecimal.ZERO, new BigDecimal("0.04"));
        sa.loadData();  // throws FileNotFoundException (narrower than IOException) ✅
    }

    @Test
    void rule3_exceptionRemoved() {
        CurrentAccount ca = new CurrentAccount("CUR001", BigDecimal.ZERO);
        ca.loadData();  // NO exception thrown — parent's IOException completely removed ✅
        // Caller doesn't even need try-catch!
    }

    // ═══ RULE 4: FINAL cannot be overridden ═══
    @Test
    void rule4_finalMethodNotOverridable() {
        Account account = new SavingsAccount("SAV001", BigDecimal.ZERO, new BigDecimal("0.04"));
        assertThat(account.getAccountId()).isEqualTo("SAV001");
        // getAccountId() is FINAL — SavingsAccount CANNOT override it.
        // Guarantees: accountId is ALWAYS what was set in constructor. No child can change this.
    }

    // ═══ RULE 4: STATIC — hidden, NOT overridden (no polymorphism) ═══
    @Test
    void rule4_staticIsHiddenNotOverridden() {
        assertThat(Account.getBankName()).isEqualTo("National Bank of India");
        assertThat(SavingsAccount.getBankName()).isEqualTo("Savings Division");

        // NO polymorphism for static:
        Account ref = new SavingsAccount("SAV001", BigDecimal.ZERO, new BigDecimal("0.04"));
        assertThat(ref.getBankName()).isEqualTo("National Bank of India");
        // ↑ Called through Account reference → Account.getBankName() at compile time!
        // If this were a regular override, it would return "Savings Division"
        // Static methods are resolved at COMPILE TIME based on VARIABLE TYPE, not actual type.
    }

    // ═══ RULE 5: @Override catches typos ═══
    @Test
    void rule5_overrideAnnotation() {
        // Without @Override: typo creates a NEW method — BUG!
        // calculateIntrest() vs calculateInterest()
        // With @Override: compiler catches "does not override" — SAFE!
        // This is tested by compilation — if it compiles with @Override, it's correct.
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        assertThat(sa.calculateInterest()).isNotNull();  // @Override verified by compiler
    }

    // ═══ LISKOV SUBSTITUTION: child works everywhere parent works ═══
    @Test
    void liskov_childSubstitutableForParent() {
        Account savings = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", new BigDecimal("500000"));

        // Both work as Account — Liskov Substitution Principle:
        InterestResult r1 = savings.calculateInterest();
        InterestResult r2 = current.calculateInterest();
        assertThat(r1.getAmount()).isGreaterThan(BigDecimal.ZERO);
        assertThat(r2.getAmount()).isEqualByComparingTo("0");
        // Wherever Account is expected, SavingsAccount or CurrentAccount works correctly.
    }
}
```
